/* Demo enhancement layer. External notifications are previews, never deliveries. */
const baseNormalise4=normalise;
normalise=function(){baseNormalise4();state.plans??=[];state.messages??=[];state.branding??={};for(const j of state.jobs){j.events??=[];j.beforePhotos??=j.photos.filter(p=>!p.phase||p.phase==='before');j.afterPhotos??=j.photos.filter(p=>p.phase==='after');j.access??={status:'Awaiting tenant',note:''};j.duration??=60}};
function addEvent(j,type,text,visibility='shared',extra={}){j.events??=[];j.events.push({id:id('e'),type,text,visibility,at:now(),...extra})}
function notify(j,type,text){state.messages??=[];state.messages.unshift({id:id('n'),job:j.id,agency:j.agency,tenant:j.tenant,type,text,at:now(),status:'Preview only — not sent'})}
function enrichChanges(before){normalise();for(const j of state.jobs){const old=before.jobs.find(x=>x.id===j.id);if(!old){addEvent(j,'Repair reported',j.title);notify(j,'New repair',j.ref+': '+j.title);continue}const seen=(arr,x)=>arr.some(y=>y.id?y.id===x.id:JSON.stringify(y)===JSON.stringify(x));for(const c of j.comments.filter(c=>!seen(old.comments,c)))addEvent(j,'Comment',c.text,c.visibility,{author:c.author,at:c.at});for(const q of j.quotes.filter(q=>!old.quotes.some(x=>x.id===q.id))){addEvent(j,'Quote uploaded',q.supplier+' · '+money(q.amount),'financial',{file:q.file,at:q.at});notify(j,'Quote uploaded',j.ref+': a quote is ready for review.')}for(const q of j.quotes){if(q.status==='Approved'&&old.quotes.find(x=>x.id===q.id)?.status!=='Approved'){addEvent(j,'Quote approved',q.supplier+' · '+money(q.amount),'financial');notify(j,'Quote approved',j.ref+': quote approved. Sevlink will arrange invoicing and the next booking step.')}}for(const i of j.invoices.filter(i=>!(old.invoices||[]).some(x=>x.id===i.id))){addEvent(j,'Invoice uploaded',i.number+' · '+money(i.amount),'financial',{file:i.file,at:i.at});notify(j,'Invoice uploaded',j.ref+': invoice '+i.number+' is available.')}if(JSON.stringify(j.schedule)!==JSON.stringify(old.schedule)&&j.schedule){addEvent(j,'Attendance '+j.schedule.status.toLowerCase(),attendanceTime(j.schedule.when));if(j.schedule.status==='Confirmed'){j.access={status:'Awaiting tenant',note:''};notify(j,'Visit confirmed',j.ref+': '+attendanceTime(j.schedule.when)+'. Please confirm access.')}}if(j.status==='Completed'&&old.status!=='Completed'){addEvent(j,'Work completed',j.completionNotes||'Completion recorded by Sevlink.');notify(j,'Repair completed',j.ref+': work completed. Your report is available.')}}}
const baseRender4=render;
render=function(){baseRender4();if(!state)return;normalise();decorateBrand();const links=[['calendar','▦','Maintenance calendar'],['notifications','✉','Updates & reminders'],...(role!=='tenant'?[['recurring','↻','Recurring maintenance']]:[])];$('#nav').insertAdjacentHTML('beforeend',links.map(([v,i,l])=>`<button data-view="${v}" class="${view===v?'active':''}">${i} &nbsp; ${l}</button>`).join(''));if(view==='calendar')renderCalendar();if(view==='notifications')renderNotifications();if(view==='recurring')renderRecurring();if(view==='properties'){app.insertAdjacentHTML('beforeend',`<div class="panel" style="margin-top:22px"><h2>Property maintenance history</h2><p>Records and costs remain attached to the property when tenants change.</p><div class="cards">${state.properties.filter(p=>canSeeProperty(p)).map(p=>`<button class="secondary" onclick="propertyHistory('${p.id}')">${esc(p.name)} →</button>`).join('')}</div></div>`)}if(view==='profile'&&isAgencyAdmin()){app.insertAdjacentHTML('beforeend','<div class="panel" style="margin-top:20px"><h2>Make this portal your own</h2><p>Upload your agency logo and choose your portal accent.</p><button class="primary" onclick="brandingForm()">Customise agency branding</button></div>')}if(view==='overview'){app.insertAdjacentHTML('afterbegin',`<div class="feature-hero"><div><span class="eyebrow">YOUR PROPERTY. OUR PRIORITY.</span><h2>Property care, from first report to final photo.</h2><p>Guided reporting · confirmed visits · one complete repair record.</p></div><button class="primary" onclick="navigate('${role==='tenant'?'report':'calendar'}')">${role==='tenant'?'Report a repair':'View maintenance calendar'} →</button></div>`)}if(view==='report')renderGuidedLanding()};
function decorateBrand(){const a=agencyNow(),b=state.branding?.[agency];const brand=$('.brand');brand.innerHTML=role==='sevlink'?'<img src="sevlink-logo.png" alt="Sevlink Property Maintenance" style="width:100%;height:130px;object-fit:contain;background:white;border-radius:10px">':`<div class="agency-brand">${b?.logo?`<img src="${b.logo.data}" alt="${esc(a.name)} logo">`:`<div class="monogram">${esc(a.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}</div>`}<b>${esc(a.name)}</b><span>Powered by <strong>SEVLINK</strong></span></div>`;document.documentElement.style.setProperty('--portal-accent',role==='sevlink'?'#01b5c1':b?.accent||'#01b5c1');$('aside footer').innerHTML=`<b>${role==='sevlink'?'Sevlink Property Maintenance':esc(a.name)}</b><br>${role==='sevlink'?'081 028 5034':esc(a.phone)}<br>${role==='sevlink'?'info@sevlink.co.za':esc(a.email)}<br><br><small>Demo workspace · browser storage<br>Messages are previews only.</small>`}
function brandingForm(){const b=state.branding[agency]||{};openForm('Your agency branding.',`<label>Portal accent</label><input type="color" name="accent" value="${esc(b.accent||'#01b5c1')}" style="height:45px"><label>Agency logo (JPG / PNG / WebP, up to 5 MB)</label><input name="logo" type="file" accept="image/jpeg,image/png,image/webp"><p>Leave the logo field empty to keep your current logo.</p>`,'Save branding',async d=>{let logo;try{logo=await fileData(d.get('logo'),imageTypes)}catch(e){toast(e.message);return}if(await commit(()=>{state.branding[agency]={accent:d.get('accent'),logo:logo||b.logo||null}})){modal.close();render();toast('Agency branding updated.')}})}
const guide={Plumbing:{icon:'🚰',issues:['Leaking tap or pipe','Blocked sink or drain','Toilet fault','Geyser issue'],questions:[['Where is the problem?',['Kitchen','Bathroom','Outside','Other']],['How much water is involved?',['Drip / small leak','Steady flow','Large leak / flooding','No leak']],['Can you still use the fixture?',['Yes','Partly','No']]]},Electrical:{icon:'💡',issues:['No power','Light or socket fault','Circuit keeps tripping','Other electrical issue'],questions:[['Which area is affected?',['One fitting / socket','One room','Whole property']],['Are there visible sparks, smoke or burning smells?',['No','Yes','Unsure']],['When did it start?',['Today','Within the last week','Longer ago']]]},'Doors & locks':{icon:'🚪',issues:['Door will not open / close','Lock or handle fault','Gate or garage door','Broken window'],questions:[['Is the property secure?',['Yes','No','Unsure']],['Can you enter and leave safely?',['Yes','No']],['Which entrance is affected?',['Front door','Internal door','Gate / garage','Window']]]},Painting:{icon:'🖌',issues:['Peeling paint','Damp stain','Cracked or damaged finish','Repainting request'],questions:[['Where is the damage?',['Inside wall','Ceiling','Outside wall','Woodwork']],['Is the area wet now?',['No','Yes','Unsure']],['How large is the affected area?',['Small patch','Part of wall / ceiling','Whole wall / ceiling']]]},Tiling:{icon:'▦',issues:['Loose tiles','Cracked tiles','Grout or sealant fault','Other tiling issue'],questions:[['Which surface is affected?',['Floor','Wall','Shower / bath edge']],['How many tiles are affected?',['1–2','3–10','More than 10']],['Is there a trip or sharp-edge hazard?',['No','Yes']]]},'General maintenance':{icon:'⌂',issues:['Roof or gutter','Cupboard or fitting','Wall or ceiling damage','Other repair'],questions:[['Where is the issue?',['Inside','Outside','Communal area']],['Is access or security affected?',['No','Yes']],['When did you first notice it?',['Today','This week','Earlier']]]}};
function renderGuidedLanding(){app.innerHTML=heading('What needs attention?','A few clear questions help us bring the right tools and people.')+(role==='tenant'?tenantSelector():'')+`<div class="reportwrap"><div class="panel"><div class="step-label">01 / SELECT A REPAIR CATEGORY</div><div class="categorygrid">${Object.entries(guide).map(([k,g])=>`<button class="category illustrated" onclick="reportForm('${k}')"><span>${g.icon}</span><b>${k}</b><small>Tell us what happened →</small></button>`).join('')}</div><div class="notice">For immediate danger, use your established emergency contact. This demo does not dispatch emergency assistance.</div></div></div>`;wireTenant()}
reportForm=function(category='Plumbing'){const g=guide[category]||guide.Plumbing,props=state.properties.filter(p=>canSeeProperty(p)&&(role!=='tenant'||p.id===state.tenants.find(t=>t.id===tenant)?.property));if(!props.length){toast('Add a property and link a tenant before reporting a repair.');return}openForm(g.icon+' '+category+' repair',`<div class="step-label">02 / HELP US UNDERSTAND THE FAULT</div><label>Property / unit</label><select name="property" id="guideProperty">${props.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select>${role==='manager'?'<label>Reported for tenant (optional)</label><select name="tenant" id="guideTenant"></select>':''}<label>What is wrong?</label><select name="issue">${g.issues.map(i=>`<option>${i}</option>`).join('')}</select>${g.questions.map(([q,answers],i)=>`<label>${q}</label><select name="answer${i}">${answers.map(a=>`<option>${a}</option>`).join('')}</select>`).join('')}<label>Additional details</label><textarea name="description" rows="3" required maxlength="2000" placeholder="Describe what happened and any useful access details."></textarea><label>Service type</label><select name="service" id="guideService"><option value="repair">Repair request / quote</option><option value="callout">Book a call-out</option></select>${role==='manager'?'<div id="guideBudgetWrap" hidden><label>Maximum total call-out budget (ZAR)</label><input name="totalBudget" id="guideBudget" type="number" min="0.01" max="10000000" step="0.01"><small>If further work exceeds this budget, Sevlink will contact the property manager and provide a quote.</small></div>':'<div id="guideBudgetWrap" class="notice" hidden>Your agency must authorise the call-out budget.</div>'}<label>Priority</label><select name="priority"><option>Normal</option><option>High</option><option>Urgent</option></select>${directAccessChoiceFields(props)}<label>Photo of the issue (optional, up to 5 MB)</label><input name="photo" type="file" accept="image/jpeg,image/png,image/webp"><div id="dangerNotice" class="notice">Do not touch exposed wiring or unsafe fixtures. If there is immediate danger, use your emergency contact.</div>`,'Send to Sevlink',async d=>{let photo;try{photo=await fileData(d.get('photo'),imageTypes)}catch(e){toast(e.message);return}const p=props.find(p=>p.id===d.get('property'));let tid=role==='tenant'?tenant:d.get('tenant');if(!p||(tid&&!state.tenants.some(t=>t.id===tid&&t.property===p.id)))return;const answers=g.questions.map(([q],i)=>({question:q,answer:d.get('answer'+i)}));if(photo){photo.phase='before';photo.at=now()}const job={id:id('j'),ref:'SV-'+(1040+state.jobs.length),agency,property:p.id,tenant:tid||'',category,title:d.get('issue'),description:d.get('description'),priority:d.get('priority'),guided:answers,status:'New',team:'Unassigned',assigned:false,photos:photo?[photo]:[],beforePhotos:photo?[photo]:[],afterPhotos:[],comments:[],quotes:[],invoices:[],schedule:null,events:[],createdAt:now(),history:['Repair reported by '+person()]};job.accessResponsibility=d.get('accessResponsibility')||property(job.property)?.accessResponsibility||'sevlink';job.clientInstructions=d.get('accessNotes')||property(job.property)?.accessInstructions||'';if(d.get('service')==='callout'){const budget=role==='manager'?Number(d.get('totalBudget')):null;if(role==='manager'&&(!Number.isFinite(budget)||budget<=0)){toast('Enter the maximum total call-out budget.');return}initialiseSimpleCallout(job,budget,role==='manager');}if(await commit(()=>state.jobs.unshift(job))){modal.close();navigate('requests');jobDetail(job.id,'history');toast('Request submitted.')}});const fill=()=>{if($('#guideTenant'))$('#guideTenant').innerHTML='<option value="">No tenant / communal repair</option>'+state.tenants.filter(t=>t.property===$('#guideProperty').value).map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')};$('#guideProperty').onchange=fill;fill();$('#guideService').onchange=()=>{const callout=$('#guideService').value==='callout';$('#guideBudgetWrap').hidden=!callout;if(role==='manager')$('#guideBudget').required=callout}};
const baseJob4=jobDetail;
jobDetail=function(jid,section='comments'){baseJob4(jid,section);const j=getJob(jid);if(!j)return;if(section==='history')renderTimeline(j);if(section==='report')renderCompletionReport(j);$('.tabs').insertAdjacentHTML('beforeend',`<button class="${section==='report'?'selected':''}" onclick="jobDetail('${jid}','report')">Before & after report</button>`);if(j.guided?.length)$('#jobcontent').insertAdjacentHTML('afterbegin',`<details class="notice"><summary>Guided repair details</summary>${j.guided.map(a=>`<p><b>${esc(a.question)}</b><br>${esc(a.answer)}</p>`).join('')}</details>`);if(j.schedule?.status==='Confirmed'&&j.status!=='Completed')$('#jobcontent').insertAdjacentHTML('afterbegin',accessPanel(j));if($('#confirmAccess'))$('#confirmAccess').onclick=()=>accessForm(j.id);if($('#jobReminder'))$('#jobReminder').onclick=()=>reminderPreview(j.id)};
function accessPanel(j){return `<div class="access-card"><b>${j.access.status==='Confirmed'?'✓ Tenant access confirmed':'Tenant access confirmation needed'}</b><p>${esc(j.access.note||'Confirm who will provide access for this appointment.')}</p>${role==='tenant'?'<button class="primary" id="confirmAccess">Confirm access / update instructions</button>':''}${role!=='tenant'?'<button class="secondary" id="jobReminder">Preview appointment reminder</button>':''}</div>`}
function accessForm(jid){const j=getJob(jid);if(!j||role!=='tenant'||j.schedule?.status!=='Confirmed')return;openForm('Confirm access for the visit.',`<p>${attendanceTime(j.schedule.when)}</p><label>Who will provide access?</label><select name="method"><option>I will be at the property</option><option>A nominated person will provide access</option><option>Please call me to arrange access</option></select><label>Access instructions (no sensitive codes)</label><textarea name="note" required rows="3" maxlength="1000" placeholder="e.g. Please call when you reach the gate."></textarea>`,'Confirm access',async d=>{if(await confirmAccess(jid,d.get('method')+'. '+d.get('note'))){render();jobDetail(jid,'schedule');toast('Tenant access confirmed.')}})}
async function confirmAccess(jid,note){const j=getJob(jid);if(!j||role!=='tenant'||j.schedule?.status!=='Confirmed')return false;return commit(()=>{j.access={status:'Confirmed',note,at:now(),by:person()};addEvent(j,'Access confirmed',note);notify(j,'Access confirmed',j.ref+': tenant has confirmed access.')})}
function timelineEntries(j){const entries=[...(j.events||[]),...j.comments.filter(c=>!j.events.some(e=>e.type==='Comment'&&e.text===c.text)).map(c=>({type:'Comment',text:c.text,at:c.at,visibility:c.visibility,author:c.author})),...j.quotes.filter(q=>!j.events.some(e=>e.type==='Quote uploaded'&&e.at===q.at)).map(q=>({type:'Quote document',text:q.supplier+' · '+money(q.amount)+' · '+q.status,at:q.at,visibility:'financial',file:q.file})),...(j.invoices||[]).filter(i=>!j.events.some(e=>e.type==='Invoice uploaded'&&e.text.startsWith(i.number+' · '))).map(i=>({type:'Invoice document',text:i.number+' · '+money(i.amount),at:i.at,visibility:'financial',file:i.file})),...j.photos.map(p=>({type:p.phase==='after'?'After photo':'Repair photo',text:p.name,at:p.at||null,visibility:'shared',file:p}))];return entries.filter(e=>e.visibility!=='internal'||role==='manager').filter(e=>e.visibility!=='financial'||role!=='tenant').sort((a,b)=>Date.parse(a.at||0)-Date.parse(b.at||0))}
function renderTimeline(j){const entries=timelineEntries(j);$('#jobcontent').innerHTML=`<h2>A complete repair timeline</h2><p>Reports, conversations, documents and appointments in one record.</p><div class="timeline">${entries.map((e,i)=>`<div class="timeline-event"><span class="timeline-dot"></span><small>${e.at?date(e.at):'Earlier record · date not captured'}</small><h3>${esc(e.type)} ${e.visibility==='internal'?'<span class="badge Awaiting">Agency internal</span>':''}</h3><p>${esc(e.text)}</p>${e.author?'<small>'+esc(e.author)+'</small>':''}${e.file?`<div class="file"><span>${esc(e.file.name)}</span><button class="secondary" data-timelinefile="${i}">Download</button></div>`:''}</div>`).join('')||'<p>No timestamped events recorded yet.</p>'}</div>${role!=='tenant'?`<details><summary>Earlier job notes (dates not recorded)</summary>${j.history.map(h=>`<p>${esc(h)}</p>`).join('')}</details>`:''}`;modal.querySelectorAll('[data-timelinefile]').forEach(b=>b.onclick=()=>download(entries[+b.dataset.timelinefile].file))}
completionForm=function(jid){const j=getJob(jid);if(!j||role!=='sevlink'||!['Scheduled','In progress'].includes(j.status))return;openForm('Complete & document the repair.',`<label>Work carried out</label><textarea name="notes" required rows="4" maxlength="2000"></textarea><label>Before photo (optional if already attached)</label><input type="file" name="before" accept="image/jpeg,image/png,image/webp"><label>After photo</label><input type="file" name="after" accept="image/jpeg,image/png,image/webp" required><label>Checks completed / recommendations</label><textarea name="checks" required rows="3" maxlength="1500"></textarea>`,'Complete & generate report',async d=>{let before,after;try{before=await fileData(d.get('before'),imageTypes);after=await fileData(d.get('after'),imageTypes)}catch(e){toast(e.message);return}if(!after)return;if(await commit(()=>{if(before){before.phase='before';before.at=now();j.beforePhotos.push(before);j.photos.push(before)}after.phase='after';after.at=now();j.afterPhotos.push(after);j.photos.push(after);j.completionNotes=d.get('notes');j.completionChecks=d.get('checks');j.completedAt=now();j.status='Completed';j.history.push('Completion report generated by Sevlink.')})){render();jobDetail(jid,'report');toast('Completed. Before-and-after report ready.')}})};
function reportMarkup(j){return `<div class="completion-report"><div class="report-top"><img src="sevlink-logo.png" alt="Sevlink"><div><span class="eyebrow">PROPERTY MAINTENANCE</span><h1>Work completion report</h1><p>${j.ref} · ${esc(j.status)}</p></div></div><h2>${esc(property(j.property)?.name)}</h2><p>${esc(property(j.property)?.address)}<br>${esc(j.title)}<br>Completed: ${j.completedAt?date(j.completedAt):'Not yet recorded'}</p><h3>Work carried out</h3><p>${esc(j.completionNotes||'Complete the job in the Sevlink view to generate the work summary.')}</p><div class="photo-pair">${[['Before',j.beforePhotos],['After',j.afterPhotos]].map(([label,photos])=>`<div><h3>${label}</h3>${photos.length?photos.map(p=>`<img src="${p.data}" alt="${label} repair photo">`).join(''):'<div class="photo-placeholder">No '+label.toLowerCase()+' photo recorded</div>'}</div>`).join('')}</div><h3>Checks & recommendations</h3><p>${esc(j.completionChecks||'No checks recorded yet.')}</p><p class="muted">Prepared by Sevlink · Your Property. Our Priority.<br>081 028 5034 · info@sevlink.co.za</p></div>`}
function renderCompletionReport(j){$('#jobcontent').innerHTML=reportMarkup(j)+`<div class="actions"><button class="primary" id="downloadReport">Download report</button></div><p class="muted">Downloads a self-contained HTML report. Open it and use Print → Save as PDF.</p>`;$('#downloadReport').onclick=()=>downloadReport(j.id)}
function downloadReport(jid){const j=getJob(jid);if(!j)return;const a=document.createElement('a'),html=`<!doctype html><html><head><meta charset="utf-8"><title>${j.ref} — Sevlink completion report</title><style>body{max-width:850px;margin:40px auto;font:15px Arial;color:#12345a;padding:20px}p{line-height:1.7;white-space:pre-wrap}.report-top{display:flex;align-items:center;gap:25px;border-bottom:3px solid #01b5c1}.report-top img{width:120px}.photo-pair{display:grid;grid-template-columns:1fr 1fr;gap:25px}.photo-pair img{max-width:100%;max-height:350px;object-fit:contain}.photo-placeholder{background:#edf5fa;padding:50px 15px}h1{font-size:27px}.muted{color:#687b8c}@media print{body{margin:0}.photo-pair{break-inside:avoid}}</style></head><body>${reportMarkup(j).replace('<img src="sevlink-logo.png" alt="Sevlink">','<b style="font-size:26px;color:#01316c">SEV<span style="color:#01b5c1">LINK</span></b>')}</body></html>`;const url=URL.createObjectURL(new Blob([html],{type:'text/html'}));a.href=url;a.download=j.ref+'-completion-report.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
let calendarMonth=new Date(new Date().toLocaleString('en-US',{timeZone:'Africa/Johannesburg'}));calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth(),1);
function calendarJobs(){return visibleJobs().filter(j=>j.schedule?.status==='Confirmed')}
function renderCalendar(){const jobs=calendarJobs(),year=calendarMonth.getFullYear(),month=calendarMonth.getMonth(),days=new Date(year,month+1,0).getDate(),offset=(new Date(year,month,1).getDay()+6)%7;const counts=new Map();jobs.forEach(j=>{let day=j.schedule.when.slice(0,10);counts.set(day,(counts.get(day)||0)+1)});app.innerHTML=heading('Every visit, clearly planned.','Confirmed attendance in SAST. Team capacity is a demo estimate.')+`<div class="panel"><div class="panelhead"><button class="secondary" onclick="moveMonth(-1)">← Previous</button><h2>${calendarMonth.toLocaleDateString('en-ZA',{month:'long',year:'numeric'})}</h2><button class="secondary" onclick="moveMonth(1)">Next →</button></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="cal-head">${d}</div>`).join('')}${Array.from({length:offset},()=>'<div class="cal-day muted"></div>').join('')}${Array.from({length:days},(_,i)=>{let key=year+'-'+String(month+1).padStart(2,'0')+'-'+String(i+1).padStart(2,'0');return `<div class="cal-day"><b>${i+1}</b>${jobs.filter(j=>j.schedule.when.startsWith(key)).map(j=>`<button class="cal-event" onclick="jobDetail('${j.id}','schedule')">${j.schedule.when.slice(11)} · ${role==='sevlink'?esc(j.title):'Sevlink attending'}<small>${role==='sevlink'?esc(j.team):esc(property(j.property)?.name)+' · '+esc(j.title)}</small></button>`).join('')}</div>`}).join('')}</div></div><div class="panel" style="margin-top:20px"><h2>Upcoming visits & team availability</h2><p>${role==='sevlink'?'Indicative capacity: 4 visits per team per day. Existing bookings are counted; travel time is not calculated.':'Only visits linked to your workspace are shown.'}</p>${jobs.sort((a,b)=>a.schedule.when.localeCompare(b.schedule.when)).map(j=>`<div class="listline toolbar"><div style="flex:1"><b>${attendanceTime(j.schedule.when)}</b><p>${esc(property(j.property)?.name)} · ${role==='sevlink'?esc(j.team):'Sevlink attending'}<br>Access: ${esc(j.access.status)}</p></div><button class="secondary" onclick="jobDetail('${j.id}','schedule')">Open visit</button></div>`).join('')||'<p>No confirmed visits yet. Approve a quote and confirm a date to populate your calendar.</p>'}${role==='sevlink'?`<div class="notice"><label>Check team availability on a date (SAST)</label><input id="availabilityDate" type="date" value="${new Date(Date.now()+2*3600000).toISOString().slice(0,10)}"><div id="availabilityResults"></div></div>`:''}</div>`;if($('#availabilityDate')&&role==='sevlink'){$('#availabilityDate').onchange=()=>showAvailability($('#availabilityDate').value);showAvailability($('#availabilityDate').value)}}
function moveMonth(delta){calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+delta,1);renderCalendar()}
function reminderPreview(jid){const j=getJob(jid);if(!j||!j.schedule)return;const t=state.tenants.find(t=>t.id===j.tenant);modal.innerHTML=`<button class="close" onclick="modal.close()">×</button><span class="eyebrow">APPOINTMENT REMINDER PREVIEW</span><h1>Your Sevlink visit</h1><div class="notice"><b>WhatsApp:</b> ${esc(t?.phone||'Tenant phone not recorded')}<br><b>Email:</b> ${esc(t?.email||'Tenant email not recorded')}</div><p>Hi ${esc(t?.name||'there')}, this is a reminder of your Sevlink maintenance visit at ${esc(property(j.property)?.name)} on ${attendanceTime(j.schedule.when)}.</p><p>Please confirm access in your tenant portal. Reference: ${j.ref}.</p><div class="notice">Preview only. A live system would send reminders 24 hours and 2 hours before the visit. No messages are sent by this demo.</div><button class="secondary" onclick="jobDetail('${jid}','schedule')">Back to visit</button>`;if(!modal.open)modal.showModal()}
function renderNotifications(){const jobs=visibleJobs(),allowed=new Set(jobs.map(j=>j.id)),msgs=state.messages.filter(m=>allowed.has(m.job)&&(role!=='tenant'||!['Invoice uploaded','Quote uploaded'].includes(m.type)));app.innerHTML=heading('Everyone stays in the loop.','Preview WhatsApp and email updates for each stage of maintenance.')+`<div class="notice"><b>Demo delivery status:</b> no messages sent. Real WhatsApp, email and background reminders need a connected delivery service.</div><div class="cards"><div class="card"><span class="eyebrow">AUTOMATIC UPDATES</span><h2>WhatsApp + email</h2><p>New repairs · quote decisions · confirmed visits · completion reports · invoices</p><span class="badge">Preview mode</span></div><div class="card"><span class="eyebrow">APPOINTMENT REMINDERS</span><h2>24 hours + 2 hours</h2><p>Reminders request tenant access confirmation before attendance.</p><span class="badge">No background delivery</span></div></div><div class="panel" style="margin-top:20px"><h2>Notification previews</h2>${msgs.map(m=>`<div class="listline"><span class="eyebrow">${esc(m.type)} · ${date(m.at)}</span><p>${esc(m.text)}</p><span class="badge">WhatsApp / email preview · not sent</span></div>`).join('')||'<p>Take an action on a repair to generate a notification preview.</p>'}</div><div class="panel" style="margin-top:20px"><h2>Visit reminder previews</h2>${jobs.filter(j=>j.schedule?.status==='Confirmed'&&j.status!=='Completed').map(j=>`<div class="listline toolbar"><div style="flex:1">${esc(j.title)}<p>${attendanceTime(j.schedule.when)}</p></div><button class="secondary" onclick="reminderPreview('${j.id}')">Preview reminder</button></div>`).join('')||'<p>Confirm a visit to see reminder previews.</p>'}</div>`}
function allowedProperties(){const ids=new Set(visibleJobs().map(j=>j.property));return state.properties.filter(p=>role==='sevlink'?ids.has(p.id):canSeeProperty(p)&&(role!=='tenant'||p.id===state.tenants.find(t=>t.id===tenant)?.property))}
function propertyHistory(pid){const p=allowedProperties().find(p=>p.id===pid);if(!p||role==='tenant')return;const jobs=state.jobs.filter(j=>j.property===pid&&(role!=='sevlink'||j.assigned));const quoteTotal=jobs.reduce((n,j)=>n+j.quotes.filter(q=>q.status==='Approved').reduce((a,q)=>a+q.amount,0),0),invoiceTotal=jobs.reduce((n,j)=>n+(j.invoices||[]).reduce((a,i)=>a+i.amount,0),0);modal.innerHTML=`<button class="close" onclick="modal.close()">×</button><span class="eyebrow">PROPERTY MAINTENANCE HISTORY</span><h1>${esc(p.name)}</h1><p>${esc(p.address)}</p><div class="cards"><div class="notice"><b>Approved quotes</b><br>${money(quoteTotal)}</div><div class="notice"><b>Invoices recorded</b><br>${money(invoiceTotal)}</div></div><p>Quote and invoice totals are separate measures, not added together.</p>${jobs.map(j=>`<div class="listline"><div class="toolbar"><div style="flex:1"><b>${esc(j.title)}</b><p>${j.ref} · ${j.createdAt?date(j.createdAt):'Earlier repair record'}<br>${esc(j.status)}</p></div><button class="secondary" onclick="jobDetail('${j.id}','history')">View record</button></div></div>`).join('')||'<p>No repair history yet.</p>'}<div class="notice">Repair records stay attached to this property when tenants move out. A new tenant does not receive the previous tenant’s repair conversations.</div>`;if(!modal.open)modal.showModal()}
function renderRecurring(){const props=allowedProperties(),plans=state.plans.filter(p=>props.some(x=>x.id===p.property));app.innerHTML=heading('Stay ahead of the next repair.','Plan inspections and repeat maintenance across your properties.',role!=='tenant'?'<button class="primary" onclick="planForm()">＋ Add recurring task</button>':'')+`<div class="cards">${plans.map(p=>`<div class="card"><span class="eyebrow">${esc(p.frequency)} MAINTENANCE</span><h2>${esc(p.title)}</h2><p>${esc(property(p.property)?.name)}<br>Next due: ${esc(p.next)}<br>Team: ${esc(p.team)}</p><p>${esc(p.notes)}</p><span class="badge">${p.paused?'Paused':'Active'}</span><div class="actions">${!p.paused?`<button class="primary" onclick="generateRecurring('${p.id}')">Create next work order</button>`:''}<button class="secondary" onclick="togglePlan('${p.id}')">${p.paused?'Resume':'Pause'}</button></div></div>`).join('')||'<div class="panel"><p>No recurring tasks yet. Add gutter cleaning, a property inspection or another regular service.</p></div>'}</div><div class="notice">In this sample, “Create next work order” generates the repair and advances the next due date. Automatic background generation and reminders are not connected.</div>`}
function planForm(){const props=allowedProperties();if(!props.length){toast('Add a property first.');return}openForm('Plan recurring maintenance.',field('Task name','title','Gutter inspection & cleaning')+`<label>Property / unit</label><select name="property">${props.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><label>Repeat</label><select name="frequency"><option>Monthly</option><option>Quarterly</option><option>Every 6 months</option><option>Yearly</option></select><label>Next due date</label><input name="next" type="date" required><label>Team</label><select name="team"><option>Sevlink Repairs Team</option><option>Sevlink Plumbing Team</option><option>Sevlink Electrical Team</option></select><label>Task notes</label><textarea name="notes" rows="3" maxlength="1000"></textarea>`,'Save recurring task',async d=>{if(!props.some(p=>p.id===d.get('property')))return;if(await commit(()=>state.plans.push({id:id('plan'),agency:property(d.get('property')).agency,...Object.fromEntries(d),paused:false,lastGenerated:null}))){modal.close();render();toast('Recurring task saved.')}})}
function advanceDate(value,frequency){const [y,m,d]=value.split('-').map(Number),step={'Monthly':1,'Quarterly':3,'Every 6 months':6,'Yearly':12}[frequency];const target=new Date(Date.UTC(y,m-1+step,1)),last=new Date(Date.UTC(target.getUTCFullYear(),target.getUTCMonth()+1,0)).getUTCDate();target.setUTCDate(Math.min(d,last));return target.toISOString().slice(0,10)}
async function generateRecurring(pid){const plan=state.plans.find(p=>p.id===pid&&allowedProperties().some(x=>x.id===p.property));if(!plan||plan.paused||role==='tenant')return;let due=plan.next;if(state.jobs.some(j=>j.plan===pid&&j.planDue===due)){toast('A work order already exists for that due date.');return}if(await commit(()=>{state.jobs.unshift({id:id('j'),ref:'SV-'+(1040+state.jobs.length),agency:plan.agency,property:plan.property,tenant:'',title:plan.title,description:plan.notes||'Planned maintenance task',category:'General maintenance',priority:'Normal',status:'New',team:plan.team,assigned:true,photos:[],beforePhotos:[],afterPhotos:[],comments:[],quotes:[],invoices:[],events:[],history:['Generated from recurring maintenance, due '+due],createdAt:now(),plan:pid,planDue:due});plan.lastGenerated=due;plan.next=advanceDate(due,plan.frequency)})){render();toast('Work order created. Next due date advanced.')}}
async function togglePlan(pid){const p=state.plans.find(p=>p.id===pid&&allowedProperties().some(x=>x.id===p.property));if(!p||role==='tenant')return;if(await commit(()=>p.paused=!p.paused))render()}
function demoIllustration(phase){const crack=phase==='before'?'<path d="M75 95l20 25-14 16 28 30" fill="none" stroke="#cf654a" stroke-width="5"/>':'<path d="M80 130l18 18 34-40" fill="none" stroke="#01b5c1" stroke-width="8"/>';const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="480" height="300" viewBox="0 0 240 150"><rect width="240" height="150" fill="#e9f2f8"/><path d="M20 135V40h200v95z" fill="#fff" stroke="#c1d4e3"/><path d="M20 90h200M70 40v95M120 40v95M170 40v95" stroke="#c1d4e3"/><rect x="135" y="50" width="55" height="30" rx="9" fill="#daeaf3" stroke="#1f5e8a"/><path d="M163 50V35h15" fill="none" stroke="#1f5e8a" stroke-width="5"/>${crack}<rect y="0" width="240" height="24" fill="#01316c"/><text x="12" y="16" font-family="Arial" font-size="10" fill="white">${phase.toUpperCase()} - DEMONSTRATION ILLUSTRATION</text></svg>`;return {name:phase+'-demo-illustration.svg',type:'image/svg+xml',data:'data:image/svg+xml;base64,'+btoa(svg),phase,at:now()}}
function ensureFeatureExamples(){if(state.featureExamples===4)return;normalise();const target=state.agencies.find(a=>a.id==='a1'),p=state.properties.find(p=>p.id==='p1'),t=state.tenants.find(t=>t.id==='t1');if(!target||!p||!t){state.featureExamples=4;return}let future=new Date(Date.now()+2*86400000+2*3600000).toISOString().slice(0,10)+'T10:00';const before=demoIllustration('before'),after=demoIllustration('after');const common={agency:'a1',property:'p1',tenant:'t1',category:'General maintenance',priority:'Normal',team:'Sevlink Repairs Team',assigned:true,comments:[],invoices:[],history:[],events:[],createdAt:now(),access:{status:'Awaiting tenant',note:''},duration:60};state.jobs.push({...structuredClone(common),id:id('demo'),ref:'DEMO-VISIT',title:'Demo: bathroom fitting repair',description:'Feature example: a confirmed visit ready for tenant access confirmation.',status:'Scheduled',quotes:[{id:id('q'),supplier:'Sevlink',amount:850,scope:'Demonstration quote',file:null,status:'Approved',at:now()}],photos:[],beforePhotos:[],afterPhotos:[],schedule:{when:future,status:'Confirmed',by:'Sevlink demo',note:'Demonstration appointment',at:now()}});const done={...structuredClone(common),id:id('demo'),ref:'DEMO-REPORT',title:'Demo: bathroom tile repair',description:'Completed example with illustrative before-and-after visuals.',status:'Completed',quotes:[],photos:[before,after],beforePhotos:[before],afterPhotos:[after],schedule:null,completedAt:now(),completionNotes:'Loose bathroom tile re-bedded and grout renewed. This is a demonstration record.',completionChecks:'Surface checked for stability. Illustrations shown are examples, not job photographs.'};addEvent(done,'Work completed',done.completionNotes);state.jobs.push(done);state.plans.push({id:id('plan'),agency:'a1',property:'p1',title:'Demo: quarterly gutter inspection',frequency:'Quarterly',next:future.slice(0,10),team:'Sevlink Repairs Team',notes:'Inspect gutters and downpipes; record any defects.',paused:false});notify(state.jobs.find(j=>j.ref==='DEMO-VISIT'),'Visit confirmed','Demo visit confirmed: '+attendanceTime(future)+'. Please confirm access.');state.featureExamples=4}
const normaliseExamples=normalise;
normalise=function(){normaliseExamples();if(!state.featureExamples&&!initialisingExamples){initialisingExamples=true;ensureFeatureExamples();initialisingExamples=false}};
let initialisingExamples=false;
function teamAvailability(day){const jobs=state.jobs.filter(j=>j.schedule?.status==='Confirmed'&&j.status!=='Completed'&&j.schedule.when.startsWith(day));return ['Sevlink Repairs Team','Sevlink Plumbing Team','Sevlink Electrical Team','Sevlink Painting Team'].map(team=>{const bookings=jobs.filter(j=>j.team===team);return {team,count:bookings.length,remaining:Math.max(0,4-bookings.length),times:bookings.map(j=>j.schedule.when.slice(11))}})}
function showAvailability(day){$('#availabilityResults').innerHTML=teamAvailability(day).map(t=>`<p><b>${t.team}</b>: ${t.remaining} of 4 visit slots available${t.times.length?' · booked '+t.times.join(', '):''}</p>`).join('')}
function scheduleConflict(j,when){const start=Date.parse(when+'+02:00'),end=start+(j.duration||60)*60000;return state.jobs.find(other=>other.id!==j.id&&other.assigned&&other.team===j.team&&other.schedule?.status==='Confirmed'&&other.status!=='Completed'&&start<Date.parse(other.schedule.when+'+02:00')+(other.duration||60)*60000&&end>Date.parse(other.schedule.when+'+02:00'))}
const baseSaveSchedule4=saveSchedule;
saveSchedule=async function(jid,when,note,agreed=false,byPhone=false){const j=getJob(jid);if(j&&agreed&&role==='sevlink'&&scheduleConflict(j,when)){toast('This team already has an overlapping visit. Choose another time.');return false}return baseSaveSchedule4(jid,when,note,agreed,byPhone)};
const baseApproveDate4=approveDate;
approveDate=async function(jid){const j=getJob(jid);if(j&&role==='sevlink'&&j.schedule&&scheduleConflict(j,j.schedule.when)){toast('Team already booked at this time. Call the tenant and record an alternative.');return}return baseApproveDate4(jid)};

